package com.acme.hr.payroll;

import java.util.List;

/**
 * Blocks a payroll run if any employee in the group lacks valid bank details.
 */
public class BankDetailsCompletenessGuard {

    private final EmployeeRepository employees;

    public BankDetailsCompletenessGuard(EmployeeRepository employees) {
        this.employees = employees;
    }

    public void assertComplete(String payGroupId) {
        List<Employee> members = employees.findActiveInPayGroup(payGroupId);
        for (Employee e : members) {
            BankAccount account = e.getBankAccount();
            if (account == null || isBlank(account.getSortCode()) || isBlank(account.getAccountNumber())) {
                throw new IncompleteBankDetailsException(e.getId());
            }
        }
    }

    private boolean isBlank(String s) {
        return s == null || s.isBlank();
    }
}

class IncompleteBankDetailsException extends RuntimeException {
    public IncompleteBankDetailsException(String id) {
        super("Employee " + id + " has incomplete bank details");
    }
}

