package com.acme.hr.payroll;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Computes gross pay from base salary, overtime hours and approved bonus.
 */
public class GrossPayCalculator {

    private final OvertimePolicy overtimePolicy;

    public GrossPayCalculator(OvertimePolicy overtimePolicy) {
        this.overtimePolicy = overtimePolicy;
    }

    public BigDecimal compute(PayPeriod period, EmployeeCompensation comp) {
        BigDecimal base = comp.getMonthlyBase();
        BigDecimal hourlyRate = base.divide(BigDecimal.valueOf(comp.getContractedMonthlyHours()), 4, RoundingMode.HALF_UP);
        BigDecimal overtime = hourlyRate
            .multiply(overtimePolicy.rateFor(period, comp.getGrade()))
            .multiply(BigDecimal.valueOf(period.getOvertimeHours()))
            .setScale(2, RoundingMode.HALF_UP);
        BigDecimal bonus = comp.getApprovedBonus() == null ? BigDecimal.ZERO : comp.getApprovedBonus();
        return base.add(overtime).add(bonus).setScale(2, RoundingMode.HALF_UP);
    }
}

