package com.acme.hr.contracts;

import java.math.BigDecimal;
import java.time.LocalDate;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Creates a new contract for an employee, validating salary against the band.
 */
@RestController
public class ContractCreationController {

    private final ContractRepository contracts;
    private final SalaryBandRepository bands;

    public ContractCreationController(ContractRepository contracts, SalaryBandRepository bands) {
        this.contracts = contracts;
        this.bands = bands;
    }

    @PostMapping("/contracts")
    public ContractView create(@RequestBody ContractRequest req) {
        SalaryBand band = bands.require(req.getBandCode());
        BigDecimal salary = req.getAnnualSalary();
        if (salary.compareTo(band.getMinimum()) < 0 || salary.compareTo(band.getMaximum()) > 0) {
            throw new IllegalArgumentException("Salary outside band " + req.getBandCode());
        }
        if (req.getEffectiveFrom().isBefore(LocalDate.now().minusDays(1))) {
            throw new IllegalArgumentException("Effective date too far in the past");
        }
        Contract c = new Contract(req.getEmployeeId(), req.getBandCode(), salary, req.getEffectiveFrom());
        return ContractView.from(contracts.save(c));
    }
}

