package com.acme.hr.leave;

import java.time.LocalDate;

/**
 * Handles a holiday request with entitlement and cover checks.
 */
public class HolidayRequestService {

    private final LeaveEntitlementRepository entitlements;
    private final TeamCoverPolicy coverPolicy;
    private final LeaveRequestRepository requests;

    public HolidayRequestService(LeaveEntitlementRepository entitlements,
                                 TeamCoverPolicy coverPolicy,
                                 LeaveRequestRepository requests) {
        this.entitlements = entitlements;
        this.coverPolicy = coverPolicy;
        this.requests = requests;
    }

    public LeaveRequest submit(String employeeId, LocalDate from, LocalDate to) {
        int days = (int) (to.toEpochDay() - from.toEpochDay()) + 1;
        if (entitlements.remainingDays(employeeId) < days) {
            throw new InsufficientLeaveException(employeeId, days);
        }
        if (!coverPolicy.hasAdequateCover(employeeId, from, to)) {
            throw new CoverUnavailableException(employeeId, from, to);
        }
        return requests.save(LeaveRequest.pending(employeeId, from, to, days));
    }
}

