package com.acme.hr.payroll;

import java.time.YearMonth;
import java.util.List;

/**
 * Orchestrates a monthly payroll run across a pay group.
 */
public class MonthlyPayrollRunner {

    private final EmployeeRepository employees;
    private final GrossPayCalculator grossPay;
    private final DeductionCalculator deductions;
    private final PayslipRepository payslips;

    public MonthlyPayrollRunner(EmployeeRepository employees, GrossPayCalculator grossPay,
                                 DeductionCalculator deductions, PayslipRepository payslips) {
        this.employees = employees;
        this.grossPay = grossPay;
        this.deductions = deductions;
        this.payslips = payslips;
    }

    public PayrollRunResult run(String payGroupId, YearMonth month) {
        List<Employee> members = employees.findActiveInPayGroup(payGroupId);
        PayrollRunResult result = new PayrollRunResult(month);
        for (Employee e : members) {
            PayPeriod period = PayPeriod.of(month, e);
            var gross = grossPay.compute(period, e.getCompensation());
            var ded = deductions.compute(period, e.getCompensation());
            Payslip slip = Payslip.create(e, period, gross, ded);
            payslips.save(slip);
            result.add(slip);
        }
        return result;
    }
}

