package com.acme.hr.security;

import org.springframework.security.access.AccessDeniedException;

/**
 * Decides whether a viewer may see an employee's salary details.
 */
public class SalaryViewPolicy {

    private final EmployeeRepository employees;
    private final StaffDirectory staff;

    public SalaryViewPolicy(EmployeeRepository employees, StaffDirectory staff) {
        this.employees = employees;
        this.staff = staff;
    }

    public void assertMayView(String viewerId, String employeeId) {
        if (viewerId.equals(employeeId)) {
            return;
        }
        if (staff.hasRole(viewerId, "HR")) {
            return;
        }
        Employee target = employees.require(employeeId);
        if (viewerId.equals(target.getLineManagerId())) {
            return;
        }
        throw new AccessDeniedException("Viewer " + viewerId + " may not see salary for " + employeeId);
    }
}

