package com.acme.hr.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Writes an immutable audit entry for salary and bank-detail changes.
 */
public class CompensationChangeAuditor {

    private final EntityManager em;

    public CompensationChangeAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String employeeId, String field, String oldValue, String newValue, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            CompensationAuditEntry entry = new CompensationAuditEntry();
            entry.setEmployeeId(employeeId);
            entry.setField(field);
            entry.setOldValue(oldValue);
            entry.setNewValue(newValue);
            entry.setActorId(actorId);
            entry.setOccurredAt(Instant.now());
            em.persist(entry);
            tx.commit();
        } catch (RuntimeException e) {
            tx.rollback();
            throw e;
        }
    }
}

