/* bank_payment_file.c - produce BACS-style payment file for a payroll run */
#include <stdio.h>
#include "payroll_db.h"

int write_payment_file(const char *pay_month, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "employee_ref,sort_code,account_number,amount\n");

    db_cursor_t *cur = NULL;
    if (db_open_payslip_cursor(&cur, pay_month) != DB_OK) { fclose(out); return -2; }

    payslip_row_t row;
    int lines = 0;
    while (db_payslip_cursor_next(cur, &row) == DB_OK) {
        if (row.on_unpaid_leave) continue;
        if (row.net_pay <= 0) continue;
        fprintf(out, "%s,%s,%s,%.2f\n",
                row.employee_ref, row.sort_code, row.account_number, row.net_pay);
        lines++;
    }
    db_close_cursor(cur);
    fclose(out);
    return lines;
}

